const response = $input.first().json;
const content = response.content[0].text;

try {
  const parsed = JSON.parse(content);

  if (!parsed.topics_found || parsed.topics_found.length === 0) {
    return [{ json: { has_topics: false, message: 'No interesting topics found in this scan.' } }];
  }

  return parsed.topics_found.map(topic => ({
    json: {
      has_topics: true,
      ...topic
    }
  }));
} catch (e) {
  return [{ json: { has_topics: false, error: 'Failed to parse Claude response', raw: content } }];
}

const response = $input.first().json;
const content = response.content[0].text;

try {
  const parsed = JSON.parse(content);
  return [{ json: parsed }];
} catch (e) {
  // If Claude returns markdown-wrapped JSON, strip it
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  try {
    return [{ json: JSON.parse(cleaned) }];
  } catch (e2) {
    return [{ json: { error: 'Failed to parse content creator response', raw: content } }];
  }
}

const post = $input.first().json;

const linkedinSection = post.linkedin_post ? 
  `*LinkedIn Post:*
>${post.linkedin_post.text.split('
').join('
>')}

_Hashtags:_ ${post.linkedin_post.hashtags.join(' ')}
_Image:_ ${post.linkedin_post.has_image ? post.linkedin_post.image_instructions : 'None'}` :
  '*LinkedIn Post:* Not generated';

const xSection = post.x_post ?
  `*X Post:*
>${post.x_post.text}
${post.x_post.thread && post.x_post.thread.length > 0 ? '
_Thread:_
' + post.x_post.thread.map((t, i) => `>${i+2}. ${t}`).join('
') : ''}
_Image:_ ${post.x_post.has_image ? post.x_post.image_instructions : 'None'}` :
  '*X Post:* Not generated';

const slackMessage = `*Social Post Draft for Approval*
━━━━━━━━━━━━━━━━━━━━━━━━━

*Topic:* ${post.topic_id}

---

${linkedinSection}

---

${xSection}

---

*Posting Notes:* ${post.posting_notes || 'None'}

━━━━━━━━━━━━━━━━━━━━━━━━━
Reply with:
:white_check_mark: — Approve and post as-is
:pencil: — Approve with edits (reply with your changes)
:x: — Reject this post`;

return [{ json: { ...post, slack_approval_message: slackMessage } }];
